641	/// Parses the memory buffer.  If successfully, run a series of passes against
642	/// it and print the result.
643	static LogicalResult
644	processBuffer(raw_ostream &os, std::unique_ptr<MemoryBuffer> ownedBuffer,
645	              llvm::MemoryBufferRef sourceBuffer,
646	              const MlirOptMainConfig &config, DialectRegistry &registry,
647	              SourceMgrDiagnosticVerifierHandler *verifyHandler,
648	              llvm::ThreadPoolInterface *threadPool) {
649	  // Tell sourceMgr about this buffer, which is what the parser will pick up.
650	  auto sourceMgr = std::make_shared<SourceMgr>();
651	  // Add the original buffer to the source manager to use for determining
652	  // locations.
653	  sourceMgr->AddNewSourceBuffer(
654	      llvm::MemoryBuffer::getMemBuffer(sourceBuffer,
655	                                       /*RequiresNullTerminator=*/false),
656	      SMLoc());
657	  sourceMgr->AddNewSourceBuffer(std::move(ownedBuffer), SMLoc());
658	
659	  // Create a context just for the current buffer. Disable threading on
660	  // creation since we'll inject the thread-pool separately.
661	  MLIRContext context(registry, MLIRContext::Threading::DISABLED);
662	  if (threadPool)
663	    context.setThreadPool(*threadPool);
664	  if (verifyHandler)
665	    verifyHandler->registerInContext(&context);
666	
667	  StringRef irdlFile = config.getIrdlFile();
668	  if (!irdlFile.empty() && failed(loadIRDLDialects(irdlFile, context)))
669	    return failure();
670	
671	  // Parse the input file.
672	  context.allowUnregisteredDialects(config.shouldAllowUnregisteredDialects());
673	  if (config.shouldVerifyDiagnostics())
674	    context.printOpOnDiagnostic(false);
675	
676	  tracing::InstallDebugHandler installDebugHandler(context,
677	                                                   config.getDebugConfig());
678	
679	  // If we are in verify diagnostics mode then we have a lot of work to do,
680	  // otherwise just perform the actions without worrying about it.
681	  if (!config.shouldVerifyDiagnostics()) {
682	    SourceMgrDiagnosticHandler sourceMgrHandler(*sourceMgr, &context);
683	    DiagnosticFilter diagnosticFilter(&context,
684	                                      config.getDiagnosticVerbosityLevel(),
685	                                      config.shouldShowNotes());
686	    return performActions(os, sourceMgr, &context, config);
687	  }
688	
689	  // Do any processing requested by command line flags.  We don't care whether
690	  // these actions succeed or fail, we only care what diagnostics they produce
691	  // and whether they match our expectations.
692	  (void)performActions(os, sourceMgr, &context, config);
693	
694	  return success();
695	}
