697	std::string mlir::registerCLIOptions(llvm::StringRef toolName,
698	                                     DialectRegistry &registry) {
699	  MlirOptMainConfig::registerCLOptions(registry);
700	  registerAsmPrinterCLOptions();
701	  registerMLIRContextCLOptions();
702	  registerPassManagerCLOptions();
703	  registerDefaultTimingManagerCLOptions();
704	  tracing::DebugCounter::registerCLOptions();
705	
706	  // Build the list of dialects as a header for the --help message.
707	  std::string helpHeader = (toolName + "\nAvailable Dialects: ").str();
708	  {
709	    llvm::raw_string_ostream os(helpHeader);
710	    interleaveComma(registry.getRegisteredDialectNames(), os,
711	                    [&](auto name) { os << name; });
712	  }
713	  return helpHeader;
714	}
