716	std::pair<std::string, std::string>
717	mlir::parseCLIOptions(int argc, char **argv, llvm::StringRef helpHeader) {
718	  static cl::opt<std::string> inputFilename(
719	      cl::Positional, cl::desc("<input file>"), cl::init("-"));
720	
721	  static cl::opt<std::string> outputFilename("o", cl::desc("Output filename"),
722	                                             cl::value_desc("filename"),
723	                                             cl::init("-"));
724	  cl::ParseCommandLineOptions(argc, argv, helpHeader);
725	  return std::make_pair(inputFilename.getValue(), outputFilename.getValue());
726	}
