736	static LogicalResult printRegisteredDialects(DialectRegistry &registry) {
737	  llvm::outs() << "Available Dialects: ";
738	  interleave(registry.getRegisteredDialectNames(), llvm::outs(), ",");
739	  llvm::outs() << "\n";
740	  return success();
741	}
742	
743	static LogicalResult printRegisteredPassesAndReturn() {
744	  mlir::printRegisteredPasses();
745	  return success();
746	}
747	
748	LogicalResult mlir::MlirOptMain(llvm::raw_ostream &outputStream,
749	                                std::unique_ptr<llvm::MemoryBuffer> buffer,
750	                                DialectRegistry &registry,
751	                                const MlirOptMainConfig &config) {
752	  if (config.shouldShowDialects())
753	    return printRegisteredDialects(registry);
754	
755	  if (config.shouldListPasses())
756	    return printRegisteredPassesAndReturn();
757	
758	  // The split-input-file mode is a very specific mode that slices the file
759	  // up into small pieces and checks each independently.
760	  // We use an explicit threadpool to avoid creating and joining/destroying
761	  // threads for each of the split.
762	  ThreadPoolInterface *threadPool = nullptr;
763	
764	  // Create a temporary context for the sake of checking if
765	  // --mlir-disable-threading was passed on the command line.
766	  // We use the thread-pool this context is creating, and avoid
767	  // creating any thread when disabled.
768	  MLIRContext threadPoolCtx;
769	  if (threadPoolCtx.isMultithreadingEnabled())
770	    threadPool = &threadPoolCtx.getThreadPool();
771	
772	  SourceMgr sourceMgr;
773	  sourceMgr.AddNewSourceBuffer(
774	      llvm::MemoryBuffer::getMemBuffer(buffer->getMemBufferRef(),
775	                                       /*RequiresNullTerminator=*/false),
776	      SMLoc());
777	  // Note: this creates a verifier handler independent of the the flag set, as
778	  // internally if the flag is not set, a new scoped diagnostic handler is
779	  // created which would intercept the diagnostics and verify them.
780	  SourceMgrDiagnosticVerifierHandler sourceMgrHandler(
781	      sourceMgr, &threadPoolCtx, config.verifyDiagnosticsLevel());
782	  auto chunkFn = [&](std::unique_ptr<MemoryBuffer> chunkBuffer,
783	                     llvm::MemoryBufferRef sourceBuffer, raw_ostream &os) {
784	    return processBuffer(
785	        os, std::move(chunkBuffer), sourceBuffer, config, registry,
786	        config.shouldVerifyDiagnostics() ? &sourceMgrHandler : nullptr,
787	        threadPool);
788	  };
789	  LogicalResult status = splitAndProcessBuffer(
790	      llvm::MemoryBuffer::getMemBuffer(buffer->getMemBufferRef(),
791	                                       /*RequiresNullTerminator=*/false),
792	      chunkFn, outputStream, config.inputSplitMarker(),
793	      config.outputSplitMarker());
794	  if (config.shouldVerifyDiagnostics() && failed(sourceMgrHandler.verify()))
795	    status = failure();
796	  return status;
797	}
798	
799	LogicalResult mlir::MlirOptMain(int argc, char **argv,
800	                                llvm::StringRef inputFilename,
801	                                llvm::StringRef outputFilename,
802	                                DialectRegistry &registry) {
803	
804	  InitLLVM y(argc, argv);
805	
806	  MlirOptMainConfig config = MlirOptMainConfig::createFromCLOptions();
807	
808	  if (config.shouldShowDialects())
809	    return printRegisteredDialects(registry);
810	
811	  if (config.shouldListPasses())
812	    return printRegisteredPassesAndReturn();
813	
814	  // When reading from stdin and the input is a tty, it is often a user
815	  // mistake and the process "appears to be stuck". Print a message to let the
816	  // user know about it!
817	  if (inputFilename == "-" &&
818	      sys::Process::FileDescriptorIsDisplayed(fileno(stdin)))
819	    llvm::errs() << "(processing input from stdin now, hit ctrl-c/ctrl-d to "
820	                    "interrupt)\n";
821	
822	  // Set up the input file.
823	  std::string errorMessage;
824	  auto file = openInputFile(inputFilename, &errorMessage);
825	  if (!file) {
826	    llvm::errs() << errorMessage << "\n";
827	    return failure();
828	  }
829	
830	  auto output = openOutputFile(outputFilename, &errorMessage);
831	  if (!output) {
832	    llvm::errs() << errorMessage << "\n";
833	    return failure();
834	  }
835	  if (failed(MlirOptMain(output->os(), std::move(file), registry, config)))
836	    return failure();
837	
838	  // Keep the output file if the invocation of MlirOptMain was successful.
839	  output->keep();
840	  return success();
841	}
842	
843	LogicalResult mlir::MlirOptMain(int argc, char **argv, llvm::StringRef toolName,
844	                                DialectRegistry &registry) {
845	
846	  // Register and parse command line options.
847	  std::string inputFilename, outputFilename;
848	  std::tie(inputFilename, outputFilename) =
849	      registerAndParseCLIOptions(argc, argv, toolName, registry);
850	
851	  return MlirOptMain(argc, argv, inputFilename, outputFilename, registry);
852	}
